ALTER TABLE public.telegram_users ADD COLUMN IF NOT EXISTS report_draft jsonb;
ALTER TABLE public.telegram_users ADD COLUMN IF NOT EXISTS moderation_state text NOT NULL DEFAULT 'normal';
ALTER TABLE public.blocked_users ADD COLUMN IF NOT EXISTS is_unblockable boolean NOT NULL DEFAULT true;
CREATE TABLE public.moderation_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id bigint NOT NULL, reported_id bigint NOT NULL, context text NOT NULL, explanation text NOT NULL, evidence_file_id text, source_message_id bigint, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, resolved_by bigint);
GRANT ALL ON public.moderation_reviews TO service_role;
ALTER TABLE public.moderation_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Service role manages moderation reviews" ON public.moderation_reviews FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE INDEX moderation_reviews_pending ON public.moderation_reviews(reported_id) WHERE status='pending';
CREATE OR REPLACE FUNCTION public.report_weight(p_context text,p_category text) RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE p_context||':'||p_category WHEN 'partner:fraud' THEN 25 WHEN 'partner:harassment' THEN 15 WHEN 'partner:spam' THEN 10 WHEN 'link:fraud' THEN 25 WHEN 'link:sexual' THEN 20 WHEN 'link:promotion' THEN 10 WHEN 'link:doxxing' THEN 20 WHEN 'media:sexual' THEN 20 WHEN 'media:fraud' THEN 15 ELSE NULL END $$;
DO $patch$ DECLARE s text; BEGIN
 SELECT pg_get_functiondef('public.submit_partner_report(bigint,bigint,text)'::regprocedure) INTO s;
 s:=replace(s,'WHEN v_is_reported_premium AND v_penalty_change > 0 THEN COALESCE(penalty_points, 0)','WHEN FALSE THEN COALESCE(penalty_points, 0)');
 s:=replace(s,'WHEN v_is_reported_premium THEN unacknowledged_reports_count','WHEN FALSE THEN unacknowledged_reports_count');
 s:=replace(s,'IF v_is_reported_premium THEN','IF FALSE THEN');
 s:=replace(s,'AND report_type IN (''spam'',''sange'',''link_spam'',''media_sange'',''media_spam'')','AND penalty_change > 0');
 EXECUTE s;
 SELECT pg_get_functiondef('public.admin_process_media_report(bigint,text)'::regprocedure) INTO s;
 s:=replace(s,'IF v_is_premium THEN','IF FALSE THEN'); EXECUTE s;
 SELECT pg_get_functiondef('public.comprehensive_search_action(bigint,text,text,boolean,bigint)'::regprocedure) INTO s;
 s:=replace(s,'AND NOT v_is_premium','');
 s:=replace(s,'IF v_blocked_at + INTERVAL ''3 days'' > NOW() THEN','IF EXISTS (SELECT 1 FROM public.blocked_users WHERE user_id=p_user_id AND is_active AND NOT is_unblockable) OR v_blocked_at + INTERVAL ''3 days'' > NOW() THEN');
 s:=replace(s,'-- 1. UPSERT USER','IF EXISTS (SELECT 1 FROM public.telegram_users WHERE id=p_user_id AND moderation_state<>''normal'') THEN RETURN json_build_object(''success'',false,''action'',''show_blocked'',''error'',''moderation_hold'',''blocked_message'',''Akun dibatasi untuk peninjauan admin. Hubungi @FizaTalkCS. Pembayaran tidak membuka pembatasan.''); END IF; -- 1. UPSERT USER');
 EXECUTE s;
END $patch$;
CREATE OR REPLACE FUNCTION public.guard_moderation_state() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.state IN ('chatting','waiting') AND NEW.moderation_state<>'normal' THEN RAISE EXCEPTION 'Account under moderation'; END IF; IF NEW.state='chatting' AND EXISTS(SELECT 1 FROM telegram_users WHERE id=NEW.partner_id AND moderation_state<>'normal') THEN RAISE EXCEPTION 'Partner under moderation'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_moderation_state BEFORE INSERT OR UPDATE OF state,partner_id ON public.telegram_users FOR EACH ROW EXECUTE FUNCTION public.guard_moderation_state();
CREATE OR REPLACE FUNCTION public.guard_protected_block() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.is_active AND NOT OLD.is_unblockable THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_protected_block BEFORE UPDATE ON public.blocked_users FOR EACH ROW EXECUTE FUNCTION public.guard_protected_block();
CREATE OR REPLACE FUNCTION public.begin_report_draft(p_reporter_id bigint,p_reported_id bigint,p_context text,p_source_id bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public SET timezone='Asia/Jakarta' AS $$ DECLARE u telegram_users; BEGIN IF p_context NOT IN ('partner','media') OR p_reporter_id=p_reported_id THEN RETURN jsonb_build_object('success',false); END IF; SELECT * INTO u FROM telegram_users WHERE id=p_reporter_id FOR UPDATE; IF u.id IS NULL OR (u.partner_id IS DISTINCT FROM p_reported_id AND NOT p_reported_id=ANY(COALESCE(u.last_partners[1:2],'{}'::bigint[]))) THEN RETURN jsonb_build_object('success',false,'error','partner_not_recent'); END IF; UPDATE telegram_users SET report_draft=jsonb_build_object('target',p_reported_id,'context',p_context,'source_id',p_source_id,'expires_at',now()+interval '30 minutes') WHERE id=p_reporter_id; RETURN jsonb_build_object('success',true); END $$;
CREATE OR REPLACE FUNCTION public.cancel_report_draft(p_user_id bigint) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE telegram_users SET report_draft=NULL WHERE id=p_user_id AND report_draft IS NOT NULL $$;
CREATE OR REPLACE FUNCTION public.submit_context_report(p_reporter_id bigint,p_reported_id bigint,p_context text,p_category text,p_explanation text DEFAULT NULL,p_evidence text DEFAULT NULL,p_source_id bigint DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public SET timezone='Asia/Jakarta' AS $$
DECLARE u telegram_users; r jsonb; points integer; prior integer; rid uuid; partner bigint; n integer; serious integer;
BEGIN
 PERFORM id FROM telegram_users WHERE id IN (p_reporter_id,p_reported_id) ORDER BY id FOR UPDATE;
 SELECT * INTO u FROM telegram_users WHERE id=p_reporter_id;
 IF u.id IS NULL OR p_reporter_id=p_reported_id OR (u.partner_id IS DISTINCT FROM p_reported_id AND NOT p_reported_id=ANY(COALESCE(u.last_partners[1:2],'{}'::bigint[]))) THEN RETURN jsonb_build_object('success',false,'error','partner_not_recent'); END IF;
 IF p_category='danger' AND p_context IN ('partner','media') THEN
  IF u.report_draft IS NULL OR (u.report_draft->>'target')::bigint<>p_reported_id OR u.report_draft->>'context'<>p_context OR (u.report_draft->>'expires_at')::timestamptz<now() OR length(trim(COALESCE(p_explanation,'')))<10 OR length(p_explanation)>1000 OR (p_context='partner' AND p_evidence IS NULL) THEN RETURN jsonb_build_object('success',false,'error','evidence_required'); END IF;
  SELECT id INTO rid FROM moderation_reviews WHERE reporter_id=p_reporter_id AND reported_id=p_reported_id AND status='pending' LIMIT 1;
  IF rid IS NULL THEN INSERT INTO moderation_reviews(reporter_id,reported_id,context,explanation,evidence_file_id,source_message_id) VALUES(p_reporter_id,p_reported_id,p_context,p_explanation,p_evidence,p_source_id) RETURNING id INTO rid; END IF;
  SELECT partner_id INTO partner FROM telegram_users WHERE id=p_reported_id;
  UPDATE telegram_users SET moderation_state=CASE WHEN moderation_state='permanent' THEN moderation_state ELSE 'pending' END,state='idle',partner_id=NULL WHERE id=p_reported_id;
  UPDATE telegram_users SET state='idle',partner_id=NULL WHERE id=partner AND partner_id=p_reported_id;
  DELETE FROM waiting_queue WHERE user_id=p_reported_id;
  RETURN jsonb_build_object('success',true,'review_id',rid,'partner_id',partner,'pending_review',true);
 END IF;
 points:=report_weight(p_context,p_category);
 IF points IS NULL THEN RETURN jsonb_build_object('success',false,'error','invalid_report_type'); END IF;
 SELECT penalty_points INTO prior FROM telegram_users WHERE id=p_reported_id;
 r:=submit_partner_report(p_reporter_id,p_reported_id,'spam')::jsonb;
 IF NOT COALESCE((r->>'success')::boolean,false) OR COALESCE((r->>'silent')::boolean,false) THEN RETURN r; END IF;
 UPDATE partner_reports SET report_type=p_context||':'||p_category,penalty_change=points WHERE id=(SELECT id FROM partner_reports WHERE reporter_id=p_reporter_id AND reported_id=p_reported_id ORDER BY created_at DESC LIMIT 1);
 SELECT count(*) INTO n FROM partner_reports WHERE reported_id=p_reported_id AND penalty_change>0 AND created_at>=now()-interval '12 hours';
 UPDATE telegram_users SET penalty_points=GREATEST(0,COALESCE(prior,0)+points),negative_reports_count=n,shadowban_until=CASE WHEN n>=4 AND (shadowban_until IS NULL OR shadowban_until<=now()) THEN now()+interval '3 days' ELSE shadowban_until END WHERE id=p_reported_id;
 SELECT count(DISTINCT reporter_id) INTO serious FROM partner_reports WHERE reported_id=p_reported_id AND report_type IN ('partner:fraud','link:fraud','link:doxxing') AND created_at>=now()-interval '7 days';
 IF COALESCE(prior,0)+points>=100 OR (p_category IN ('fraud','doxxing') AND p_context<>'media' AND serious>=2) THEN INSERT INTO blocked_users(user_id,reason,blocked_message,is_active,blocked_at) VALUES(p_reported_id,'context_report','Akun dibatasi sementara karena laporan pelanggaran.',true,now()) ON CONFLICT(user_id) DO UPDATE SET is_active=true,blocked_at=now(),reason=EXCLUDED.reason,blocked_message=EXCLUDED.blocked_message; END IF;
 RETURN r||jsonb_build_object('penalty_change',points,'new_penalty',COALESCE(prior,0)+points,'warning',true,'is_banned',COALESCE(prior,0)+points>=100 OR serious>=2);
END $$;
CREATE OR REPLACE FUNCTION public.resolve_moderation_review(p_review_id uuid,p_action text,p_admin_id bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public SET timezone='Asia/Jakarta' AS $$ DECLARE r moderation_reviews; BEGIN SELECT * INTO r FROM moderation_reviews WHERE id=p_review_id FOR UPDATE; IF r.id IS NULL OR r.status<>'pending' OR p_action NOT IN ('ban','reject') THEN RETURN jsonb_build_object('success',false,'error','already_processed'); END IF; UPDATE moderation_reviews SET status=CASE WHEN p_action='ban' THEN 'confirmed' ELSE 'rejected' END,resolved_at=now(),resolved_by=p_admin_id WHERE id=r.id; IF p_action='ban' THEN UPDATE telegram_users SET moderation_state='permanent',state='idle',partner_id=NULL WHERE id=r.reported_id; INSERT INTO blocked_users(user_id,reason,blocked_message,is_active,blocked_at,is_unblockable) VALUES(r.reported_id,'confirmed_severe_violation','Akun diblokir permanen setelah peninjauan admin. Hubungi @FizaTalkCS.',true,now(),false) ON CONFLICT(user_id) DO UPDATE SET is_active=true,is_unblockable=false,reason=EXCLUDED.reason,blocked_message=EXCLUDED.blocked_message; ELSE IF NOT EXISTS(SELECT 1 FROM moderation_reviews WHERE reported_id=r.reported_id AND status='pending') THEN UPDATE telegram_users SET moderation_state='normal',premium_until=CASE WHEN premium_until IS NOT NULL AND premium_until>r.created_at THEN premium_until+(now()-r.created_at) ELSE premium_until END WHERE id=r.reported_id AND moderation_state='pending'; END IF; END IF; RETURN jsonb_build_object('success',true,'target',r.reported_id,'action',p_action); END $$;
REVOKE ALL ON FUNCTION public.begin_report_draft(bigint,bigint,text,bigint),public.cancel_report_draft(bigint),public.submit_context_report(bigint,bigint,text,text,text,text,bigint),public.resolve_moderation_review(uuid,text,bigint),public.admin_process_media_report(bigint,text),public.submit_partner_report(bigint,bigint,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.begin_report_draft(bigint,bigint,text,bigint),public.cancel_report_draft(bigint),public.submit_context_report(bigint,bigint,text,text,text,text,bigint),public.resolve_moderation_review(uuid,text,bigint),public.admin_process_media_report(bigint,text),public.submit_partner_report(bigint,bigint,text) TO service_role;